        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Czucie i wiara silniej mówi do mnie, Niż mędrca szkiełko i oko. „Martwe znasz prawdy, nieznane dla ludu, Widzisz świat w proszku, w każdej gwiazd iskierce; Nie znasz prawd żywych, nie obaczysz cudu! Miej serce i patrzaj w serce!”", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ciemno wszędzie, głucho wszędzie, co to będzie, co to będzie?", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Gdy na dziewczynę zawołają: żono! Już ją żywcem pogrzebano!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kobieto! puchu marny! ty wietrzna istoto!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kto miłości nie zna, ten żyje szczęśliwy, I noc ma spokojną, i dzień nietęskliwy.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bo kto siedzi w Ojczyźnie i cierpi niewolę, aby zachować życie, ten straci Ojczyznę i życie; a kto opuści Ojczyznę, aby bronił Wolności narażeniem życia swego, ten obroni Ojczyznę i będzie żyć wiecznie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Litwo! Ojczyzno moja! Ty jesteś jak zdrowie; Ile cię trzeba cenić, ten tylko się dowie, Kto cię stracił. Dziś piękność twą w całej ozdobie Widzę i opisuję, bo tęsknię po tobie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Aby kraj mógł żyć, trzeba, aby żyły prawa.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bez serc, bez ducha – to szkieletów ludy. Młodości! podaj mi skrzydła! Niech nad martwym wzlecę światem W rajską dziedzinę ułudy…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bo dzieło zniszczenia W dobrej sprawie jest święte, jak dzieło tworzenia: Bóg wyrzekł słowo ''stań się'', Bóg i ''zgiń'' wyrzecze!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bóg sam może świat zniszczyć i drugi wystawić, A bez naszej pomocy nie może nas zbawić.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Gdy cię nie widzę, nie wzdycham, nie płaczę; Nie tracę zmysłów, kiedy cię zobaczę; Jednakże, gdy cię długo nie oglądam, Czegoś mi braknie, kogoś widzieć żądam, I tęskniąc sobie zadaję pytanie: Czy to jest przyjaźń, czy to jest kochanie?", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Głośniej niźli w rozmowach, Bóg przemawia w ciszy, I kto w sercu ucichnie, zaraz go usłyszy.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Hej, użyjmy żywota!  Wszak żyjem tylko raz;  Niechaj ta czara złota Różno wabi nas.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "I was dostrzegam, o dumni badacze! Gdy wami burza jak śmieciem pomiata, Zamknięci w sobie, jak w konchy ślimacze, Chcieliście mali obejrzeć krąg świata.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Karząc plemię zwycięzców zbrodniami zatrute, Bóg wysadzi tę ziemię, jak on swą redutę.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kto metal kwasi, pali Skwasi metal i czas; My ze złotych metali Bacha ciągnijmy kwas.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Mierz siłę na zamiary, Nie zamiar podług sił!…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Na każdem miejscu i o każdej dobie, Gdziem z tobą płakał, gdziem się z tobą bawił, Wszędzie i zawsze będę ja przy tobie, Bom wszędzie cząstkę mej duszy zostawił.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Nam strzelać nie kazano. Wstąpiłem na działo I spojrzałem na pole — dwieście armat grzmiało.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Piękny kościół, w którym nie ma Boga.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Polały się łzy me czyste, rzęsiste Na me dzieciństwo sielskie, anielskie,  Na moją młodość górną i durną,  Na mój wiek męski, wiek klęski.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Potępi nas świętoszek, rozpustnik wyśmieje, Że chociaż samotnemi otoczeni ściany, Chociaż ona tak młoda, ja tak zakochany, Przecież ja oczy spuszczam, a ona łzy leje.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Precz z moich oczu! – posłucham od razu; Precz z mego serca! – i serce posłucha; Precz z mej pamięci! – nie tego rozkazu, Moja i twoja pamięć nie posłucha.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ręce za lud walczące, sam lud poobcina, Imion miłych ludowi – lud pozapomina… Wszystko przejdzie. Po szumie, po huku, po trudzie, Wezmą dziedzictwo cisi, ciemni, mali ludzie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Rozminiem się!... I kiedyż w jedną pójdziem drogę? Ty mnie szukać nie będziesz, ja ciebie nie mogę...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Słowianie utożsamili chrześcijaństwo z niemczyzną i niewolą.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Szukam północnej gwiazdy na zamglonem niebie,  Szukam Litwy, i domku twojego, i ciebie...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "„Świat ten jest czysta bajka!” Zgoda, przyjacielu: Lecz każda bajka ma sens moralny na celu.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ten może deptać węże, głaskać lwy i tury, Kto wyrwał z siebie żądło, rogi i pazury.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "W słowach tylko chęć widzim, w działaniu potęgę; Trudniej dzień dobrze przeżyć, niż napisać księgę.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Wiedzcie, że dla poety jedna tylko droga: W sercu szukać natchnienia i dążyć do Boga!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Witaj, jutrzenko swobody, Zbawienia za tobą słońce!...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Wpłynąłem na suchego przestwór oceanu Wóz nurza się w zieloność i jak łódka brodzi, Śród fali łąk szumiących, śród kwiatów powodzi, Omijam koralowe ostrowy burzanu.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Zwyciężonemu za pomnik grobowy Zostaną suche drewna szubienicy, Za całą sławę krótki płacz kobiécy I długie, nocne rodaków rozmowy…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Że słyszałbym głos z Litwy... Jedźmy, nikt nie woła!", Author = "Adam Mickiewicz" },
